package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Variance_evaluate_TriageGen1Test {

    private static final double EPSILON = 1e-9;







    @Test
    public void testEvaluate_LengthGreaterThanOne_Uncorrected() {
        // isBiasCorrected = false
        Variance variance = new Variance(false);
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0, 1.0};
        double mean = 2.0;
        int begin = 0;
        int length = 3;

        // Calculation:
        // sumWts = 3.0
        // dev: (1-2)=-1, (2-2)=0, (3-2)=1
        // accum = 1*(1)^2 + 1*(0)^2 + 1*(1)^2 = 2.0
        // accum2 = 1*(-1) + 1*(0) + 1*(1) = 0.0
        // var = (2.0 - (0.0 * 0.0 / 3.0)) / 3.0 = 2/3 = 0.6666666666666666

        double result = variance.evaluate(values, weights, mean, begin, length);
        Assert.assertEquals(2.0 / 3.0, result, EPSILON);
    }






}

