import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Variance_evaluate_TriageGen1Test {

    private static final double EPSILON = 1e-9;











    @Test
    public void testEvaluate_WeightedCalculation() {
        // Test with non-uniform weights
        Variance variance = new Variance(false);
        double[] values = {1.0, 3.0};
        double[] weights = {1.0, 3.0}; // sumWts = 4.0
        double mean = 2.5; // (1*1 + 3*3)/4 = 10/4 = 2.5
        int begin = 0;
        int length = 2;

        // dev: (1-2.5)=-1.5, (3-2.5)=0.5
        // accum = 1.0*(-1.5)^2 + 3.0*(0.5)^2 = 2.25 + 0.75 = 3.0
        // accum2 = 1.0*(-1.5) + 3.0*(0.5) = -1.5 + 1.5 = 0.0
        // var = (3.0 - 0) / 4.0 = 0.75

        double result = variance.evaluate(values, weights, mean, begin, length);
        Assert.assertEquals(0.75, result, EPSILON);
    }


}

package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
